```cpp
#include <bits/stdc++.h>
using namespace std;

long long fast_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            res = res * base % mod;
        }
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    int k;
    long long m;
    cin >> k >> m;
    vector<int> a(k);
    for (int i = 0; i < k; ++i) {
        cin >> a[i];
    }

    vector<long long> b;
    int current_value = a[k-1] % 2;  // 记录当前段的奇偶性，0表示偶数，1表示奇数
    long long count = 0;

    for (int i = k-1; i >= 0; --i) {
        if (a[i] % 2 == current_value) {  // 当前元素与上一段的奇偶性相同
            count += a[i];
        } else {
            b.push_back(count);
            current_value = a[i] % 2;
            count = a[i];
        }
    }

    // 将最后一段的长度也加到b中
    if (count != 0) {
        b.push_back(count);
    }


    // 如果首位是偶数，移除第一个元素
    if (a[0] % 2 == 0) {
        b.pop_back();
    }

    long long result = 0;
    long long exponent = 0;

    // 遍历b数组进行计算
    for (int i = 0; i < b.size(); ++i) {
        exponent += b[i];
        long long contribution = fast_pow(2, exponent - 1, m);  // 计算贡献值，模m
        result = (result + contribution) % m;
    }

    cout << result % m << endl;
    return 0;
}
