import java.util.*;

public class Main {

    static long fastPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        long m = sc.nextLong();
        int[] a = new int[k];
        for (int i = 0; i < k; i++) a[i] = sc.nextInt();

        List<Long> b = new ArrayList<>();
        int currentValue = a[k-1] % 2;  
        long count = 0;

        for (int i = k-1; i >= 0; i--) {
            if (a[i] % 2 == currentValue) {  
                count += a[i];
            } else {
                b.add(count);
                currentValue = a[i] % 2;
                count = a[i];
            }
        }

        if (count != 0) {
            b.add(count);
        }


        if (a[0] % 2 == 0) {
            b.remove(b.size() - 1);
        }

        long result = 0;
        long exponent = 0;

        for (long val : b) {
            exponent += val;
            long contribution = fastPow(2, exponent - 1, m); 
            result = (result + contribution) % m;
        }

        System.out.println(result % m);
    }
}

